"use client";

import { useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Label } from "@/components/ui/label";
import { useAddProduct } from "../useProducts";
import { createProductSchema, productStatusSchema, productCategorySchema, type ProductStatus, type ProductCategory } from "@atelier/shared";
import { Plus } from "lucide-react";
import { z } from "zod";

import { useAuth } from "@/contexts/AuthContext";

const productFormSchema = createProductSchema.extend({
  // Form-specific fields can be added here if needed
});

type ProductFormData = z.infer<typeof productFormSchema>;

interface ProductAddDialogProps {
  onProductAdded?: () => void;
}

export function ProductAddDialog({ onProductAdded }: ProductAddDialogProps) {
  const [open, setOpen] = useState(false);
  const addProduct = useAddProduct();
  const { shopId } = useAuth();

  const {
    register,
    handleSubmit,
    formState: { errors },
    setValue,
    watch,
    reset,
  } = useForm<ProductFormData>({
    resolver: zodResolver(productFormSchema),
    defaultValues: {
      shopId,
      status: "pending",
    },
  });

  const selectedStatus = watch("status");
  const selectedCategory = watch("category");

  const handleOpenChange = (newOpen: boolean) => {
    setOpen(newOpen);
    if (!newOpen) {
      reset();
    }
  };

  const onSubmit = async (data: ProductFormData) => {
    try {
      await addProduct.mutateAsync({
        shopId: data.shopId,
        name: data.name,
        brand: data.brand,
        category: data.category,
        sku: data.sku,
        handle: data.handle,
        url: data.url,
        sizeTypeId: data.sizeTypeId,
        status: data.status,
        thumbnailUrl: data.thumbnailUrl,
        previewImageUrl: data.previewImageUrl,
      });
      reset();
      setOpen(false);
      onProductAdded?.();
    } catch (error) {
      console.error("Failed to add product:", error);
    }
  };

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogTrigger asChild>
        <Button>
          <Plus className="h-4 w-4" />
          商品を追加
        </Button>
      </DialogTrigger>
      <DialogContent className="sm:max-w-[500px]">
        <DialogHeader>
          <DialogTitle>商品を追加</DialogTitle>
          <DialogDescription>
            新しい商品の情報を入力してください。
          </DialogDescription>
        </DialogHeader>
        <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="name">商品名</Label>
            <Input
              id="name"
              {...register("name")}
              placeholder="商品名を入力"
            />
            {errors.name && (
              <p className="text-sm text-red-500">{errors.name.message}</p>
            )}
          </div>

          <div className="space-y-2">
            <Label htmlFor="brand">ブランド（任意）</Label>
            <Input
              id="brand"
              {...register("brand")}
              placeholder="ブランド名を入力"
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="category">カテゴリ（任意）</Label>
            <Select
              value={selectedCategory || ""}
              onValueChange={(value: ProductCategory) =>
                setValue("category", value, { shouldValidate: true })
              }
            >
              <SelectTrigger>
                <SelectValue placeholder="カテゴリを選択" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="ジャケット">ジャケット</SelectItem>
                <SelectItem value="コート">コート</SelectItem>
                <SelectItem value="トップス">トップス</SelectItem>
                <SelectItem value="ボトムス">ボトムス</SelectItem>
              </SelectContent>
            </Select>
            {errors.category && (
              <p className="text-sm text-red-500">{errors.category.message}</p>
            )}
          </div>

          <div className="space-y-2">
            <Label htmlFor="sku">SKU（任意）</Label>
            <Input
              id="sku"
              {...register("sku")}
              placeholder="SKUを入力"
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="handle">Handle（任意）</Label>
            <Input
              id="handle"
              {...register("handle")}
              placeholder="handleを入力"
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="url">URL（任意）</Label>
            <Input
              id="url"
              {...register("url")}
              placeholder="https://..."
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="sizeTypeId">サイズタイプID（任意）</Label>
            <Input
              id="sizeTypeId"
              {...register("sizeTypeId")}
              placeholder="UUID形式で入力"
            />
            <p className="text-xs text-gray-500">
              サイズタイプのUUIDを入力してください（例: レターサイズ、数字サイズなど）
            </p>
            {errors.sizeTypeId && (
              <p className="text-sm text-red-500">{errors.sizeTypeId.message}</p>
            )}
          </div>

          <div className="space-y-2">
            <Label htmlFor="thumbnailUrl">サムネイルURL（任意）</Label>
            <Input
              id="thumbnailUrl"
              {...register("thumbnailUrl")}
              placeholder="https://..."
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="previewImageUrl">プレビュー画像URL（任意）</Label>
            <Input
              id="previewImageUrl"
              {...register("previewImageUrl")}
              placeholder="https://..."
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="status">ステータス</Label>
            <Select
              value={selectedStatus}
              onValueChange={(value: ProductStatus) =>
                setValue("status", value, { shouldValidate: true })
              }
            >
              <SelectTrigger>
                <SelectValue placeholder="ステータスを選択" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="pending">未発注</SelectItem>
                <SelectItem value="in_production">制作中</SelectItem>
                <SelectItem value="review">レビュー待ち</SelectItem>
                <SelectItem value="revision">修正中</SelectItem>
                <SelectItem value="ready">公開可</SelectItem>
                <SelectItem value="published">公開中</SelectItem>
              </SelectContent>
            </Select>
            {errors.status && (
              <p className="text-sm text-red-500">{errors.status.message}</p>
            )}
          </div>

          <DialogFooter>
            <Button
              type="button"
              variant="outline"
              onClick={() => setOpen(false)}
            >
              キャンセル
            </Button>
            <Button type="submit" disabled={addProduct.isPending}>
              {addProduct.isPending ? "追加中..." : "追加"}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}
